            reverted = false;
        } catch {
            reverted = true;
        }

        uint pot_after = c.pot();
        uint balance_after = address(c).balance;

        // GENERAL RULE:
        // If the caller did not send the exact ticket amount, the call must revert and c's state unchanged.
        // If the caller sent exactly the ticket amount, then either:
        //  - the call reverted and pot stayed the same and balance stayed the same; OR
        //  - the call succeeded and either the pot increased by amt (no payout happened), or a payout happened
        //    in which case pot is zero and contract balance decreased by the fee constant (i.e. balance_after + c.FEE_AMOUNT() == balance_before + amt - (amt - (pot_before + amt - c.FEE_AMOUNT())) simplified to balance decreased by FEE_AMOUNT).
        // We express a conservative but general invariant covering both cases below.

        if (amt != c.TICKET_AMOUNT()) {
            // must revert and no state change
            assert(reverted && pot_after == pot_before && balance_after == balance_before);
