            bool successWithPayout = (!reverted) && pot_after == 0 && balance_after + c.FEE_AMOUNT() == balance_before; 

            assert(noChangeOnRevert || successNoPayout || successWithPayout);
        }
    }

    // receive to accept refunds/payouts
    receive() external payable {}
}

