contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept a ticket payment amount and an initial deposit count to populate the pot.
    // We will first optionally send several correct ticket payments to increase pot, then
    // perform one final play() call from this contract with amount 'pay'.
    function run(uint priorPlays, uint pay) public payable {
        // Ensure the test contract has enough balance to fund all sends
        uint totalNeeded = priorPlays * c.TICKET_AMOUNT() + pay;
        require(address(this).balance >= totalNeeded);
        // Record balances and pot before any actions
        uint beforeContractBalance = address(c).balance;
        uint beforePot = c.pot();
        uint beforeThis = address(this).balance;

        // Make priorPlays successful plays from this test to build up pot (each must send exact ticket price)
        for (uint i = 0; i < priorPlays; i++) {
            // Each call must be a top-level state-changing call
            c.play{value: c.TICKET_AMOUNT()}();
        }

        // After setup, record values
        uint midPot = c.pot();
        uint midContractBalance = address(c).balance;
        uint midThis = address(this).balance;

        // Now attempt the deciding play call and catch whether it reverts
        bool reverted;
        // We will call with value 'pay'
        // require we have the funds
        require(address(this).balance >= pay);
        try c.play{value: pay}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterPot = c.pot();
        uint afterContractBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // Build the assertion: If the final call reverted then state must be unchanged from mid state.
        // If it did not revert, then exactly two possibilities hold:
        // 1) A payout occurred: pot becomes 0, contract balance decreased by FEE_AMOUNT, and caller (this)
        //    gained exactly (midPot + c.TICKET_AMOUNT()) - c.FEE_AMOUNT() (i.e., pot before plus ticket minus fee).
        // 2) No payout: pot increased by exactly c.TICKET_AMOUNT() and caller received no Ether from contract.
        // We express these using only public getters and balances.

        uint T = c.TICKET_AMOUNT();
        uint F = c.FEE_AMOUNT();

        assert(
            // If reverted: nothing changed from mid-state
            (reverted && afterPot == midPot && afterContractBalance == midContractBalance && afterThis == midThis)
            ||
            (
                // Not reverted: either payout happened
                (!reverted) && (
                    (
                        // payout branch: pot becomes 0
                        afterPot == 0
                        // contract balance decreased by exactly F compared to midContractBalance
                        && midContractBalance == afterContractBalance + F
                        // this contract's balance increased by midPot + T - F
                        && afterThis == midThis + midPot + T - F
                    )
                    ||
                    (
                        // no-payout branch: pot increased by T and this contract got no funds
                        afterPot == midPot + T
                        && afterThis == midThis
                        // contract balance increased by exactly T as it received the ticket
                        && afterContractBalance == midContractBalance + T
                    )
                )
            )
        );
    }

    receive() external payable { }
}

