    // single public test function: amount to send as ticket, and number of prior top-ups to build pot
    function run(uint amount, uint topUps) public payable {
        // We need enough ETH in this test contract to perform the setup plays and the decisive call
        // Each setup play must send exactly the ticket amount; we don't have a getter for TICKET_AMOUNT,
        // so we infer it by using the public constant behavior: require that amount is the ticket price
        // by observing that when sending wrong amount play() reverts. To keep the precondition simple,
        // require the caller supplies enough balance for topUps + 1 times `amount`.
        require(address(this).balance >= amount * (topUps + 1));

        // Build up pot by calling play topUps times with the same `amount`.
        // Some of these may revert; we still proceed — the assertion will account for reverts.
        for (uint i = 0; i < topUps; i++) {
            // Each setup call is a top-level state-changing call
            // Use try/catch to ignore reverts during setup (they leave state unchanged)
            try c.play{value: amount}() {
                // success: nothing to do here
            } catch {
                // revert: nothing to do, pot unchanged
            }
        }

        // Record before-values
        uint beforePot = c.pot();
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        // Attempt decisive call and record if it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterPot = c.pot();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // We cannot access TICKET_AMOUNT/FEE_AMOUNT directly, so deduce ticket semantics from behaviour:
        // If the decisive call did not revert, then amount must equal the ticket price; otherwise a non-ticket amount call always reverts and leaves state unchanged.
        // Formulate general rule:
        // - If reverted: state unchanged (pot and balances equal before)
        // - If not reverted: amount behaved as ticket price. Then either payout occurred: pot -> 0 and this contract gained (beforePot + amount - fee), or no payout: pot -> beforePot + amount and this contract balance unchanged.
        // Because we can't name FEE_AMOUNT, we express the payout gain as (beforeBalanceThis + (beforeBalanceC + amount - afterBalanceC)) == afterBalanceThis when payout happened,
        // since contract balance decreased by the payout amount (payout + fee decreases contract balance by payout + fee?), but simpler: when payout happens, afterPot == 0 and afterBalanceThis > beforeBalanceThis.

        // Construct the assertion accordingly.
        assert(
            // if reverted: nothing changed
            (reverted && afterPot == beforePot && afterBalanceC == beforeBalanceC && afterBalanceThis == beforeBalanceThis)
            || (
                // not reverted: treat `amount` as the ticket price
                !reverted
                && (
                    // payout branch: pot reset to 0 and this contract's balance strictly increases by some positive amount equal to (previous pot + amount - FEE)
                    (afterPot == 0 && afterBalanceThis > beforeBalanceThis && afterBalanceC + (afterBalanceThis - beforeBalanceThis) + 0 == beforeBalanceC + amount)
                    ||
                    // no-payout branch: pot increased by amount and this contract's balance did not increase
                    (afterPot == beforePot + amount && afterBalanceThis == beforeBalanceThis)
                )
            )
        );
    }

    // Allow receiving Ether from C when it pays out
    receive() external payable { }
}

