        // - If not reverted: exactly one of two behaviors must hold:
        //     (A) payout occurred: pot == 0 and this contract's balance strictly increased;
        //     (B) no payout: pot == beforePot + amount and this contract's balance unchanged.
        assert(
            (reverted && afterPot == beforePot && afterBalanceC == beforeBalanceC && afterBalanceThis == beforeBalanceThis)
            || (
                !reverted
                && (
                    (afterPot == 0 && afterBalanceThis > beforeBalanceThis)
                    || (afterPot == beforePot + amount && afterBalanceThis == beforeBalanceThis)
                )
            )
        );
    }

    // Allow receiving Ether from C when it pays out
    receive() external payable { }
}

